def prime_factorize(n):
    if n == 0:
        return [0]
    a = []
    while n % 2 == 0:
        if a and a[-1] == 2:
            a.pop()
        else:
            a.append(2)
        n //= 2
    f = 3
    while f * f <= n:
        if n % f == 0:
            if a and a[-1] == f:
                a.pop()
            else:
                a.append(f)
            n //= f
        else:
            f += 2
    if n != 1:
