    a = [iread() for _ in range(n)]
    p = [prime_factorize(x) for x in a]
    p = [f(x) for x in p]

    # Separate zeros and non-zeros
    zeros = [x for x in p if x == 0]
    non_zeros = [x for x in p if x != 0]

    # Count non-zero factors
    c = Counter(non_zeros)

